function icon(name,cls=''){return `<svg class="${cls}" viewBox="${name==='mark'?'0 0 44 44':'0 0 24 24'}" aria-hidden="true">${icons[name]||icons.file}</svg>`}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function action(name,label,cl='btn',ico='',disabled=false){return `<button class="${cl}" data-action="${esc(name)}" ${disabled?'disabled':''}>${ico?icon(ico):''}${label}</button>`}
function ib(name,label,ico){return `<button class="icon-btn" data-action="${name}" aria-label="${label}" title="${label}">${icon(ico)}</button>`}
function tag(t,cls=''){return `<span class="tag ${cls}">${t}</span>`}
function mark(cls='mark'){return `<span class="${cls}">${icon('mark')}</span>`}
