let lastRoute='';let focusBefore=null;let toastTimer=null;let compactTimer=null;
function renderV1(keepScroll=true){const old=document.querySelector('.content');const y=old&&keepScroll&&lastRoute===state.screen?old.scrollTop:0;document.documentElement.dataset.theme=state.theme;document.getElementById('phone').dataset.theme=state.theme;document.getElementById('phone-content').innerHTML=page();const c=document.querySelector('.content');if(c)c.scrollTop=y;lastRoute=state.screen;renderOverlay();renderReview();document.title=screenMap[state.screen][2]+' · AgentApp UI 原型';}
function renderOverlayV1(){const host=document.getElementById('overlay');host.innerHTML=overlay();document.getElementById('phone-content').inert=!!state.overlay;if(state.overlay){const dialog=host.querySelector('[role=dialog]');if(dialog)dialog.focus({preventScroll:true});}else if(focusBefore?.isConnected){focusBefore.focus({preventScroll:true});focusBefore=null;}}
function renderReviewV1(){let group='';document.getElementById('review-nav').innerHTML=screens.map(s=>{let head=s[3]!==group?`<div class="review-group">${s[3]}</div>`:'';group=s[3];return head+`<button class="review-item ${s[0]===state.screen?'active':''}" data-action="go:${s[0]}"><span class="num">${s[1]}</span>${s[2]}</button>`}).join('')+`<div class="review-group">关键底部面板</div>`+sheets.map(([id,t])=>`<button class="review-item ${state.overlay===id?'active':''}" data-action="review-sheet:${id}"><span class="num">↳</span>${t}</button>`).join('');const s=screenMap[state.screen];document.getElementById('review-info').innerHTML=`<div class="eyebrow">DESIGN NOTE / ${s[1]}</div><h2>${s[4]}</h2><p>${s[5]}</p><div class="rule"></div><div class="label" style="color:#8B867A">TRY THIS</div><p>${s[7]}</p><div class="rule"></div><div class="label" style="color:#8B867A">COMPOSE MAPPING</div><p><code>${s[6]}</code></p><p class="review-note">可交互的视觉规格，不是 WebView 实现方案。正式应用继续使用 Kotlin + Jetpack Compose。</p><div class="rule"></div><div class="eyebrow">WARM NEUTRALS / TERRACOTTA</div><div class="swatches"><span class="swatch" style="background:#faf9f5"></span><span class="swatch" style="background:#e8e6dc"></span><span class="swatch" style="background:#d97757"></span><span class="swatch" style="background:#262624"></span></div><p>浅色 / 深色 · 360 / 412 宽度<br>24 个页面 · 关键状态与弹层</p><p class="fine" style="color:#817B6C">仓库基线 2c94723<br>设计研究截至 2026.09.22<br><span class="kbd">Esc</span> 关闭面板</p>`;document.getElementById('theme-toggle').innerHTML=icon(state.theme==='dark'?'sun':'moon')+' '+(state.theme==='dark'?'浅色':'深色');document.querySelectorAll('[data-width]').forEach(b=>b.classList.toggle('active',b.dataset.width===(document.getElementById('phone').classList.contains('compact')?'360':'412')));}
function navigateV1(route,push=true){if(!screenMap[route])return;if(state.overlay==='compacting'){toast('请先等待或取消上下文压缩。');return;}if(push&&route!==state.screen)state.stack.push(state.screen);state.screen=route;state.overlay=null;state.query='';state.manage=false;state.selected.clear();state.permissionDraft='';state.forms.folder=false;try{history.replaceState(null,'','#'+route)}catch{}render(false);}
function showV1(o){if(state.overlay==='compacting'&&o!=='compacting')return;if(!state.overlay)focusBefore=document.activeElement;state.overlay=o;state.query='';renderOverlay();renderReview();}
function closeV1(){if(state.overlay==='compacting'){toast('请使用“取消压缩”停止操作。');return;}state.overlay=null;state.query='';renderOverlay();renderReview();}
function toastV1(t){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=t;toastTimer=setTimeout(()=>el.textContent='',3300);}
function download(name,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1500);}
function reset(){location.href=location.pathname+location.search.split('&state=')[0];}
function save(kind){const key=kind==='agents'?'agent':kind==='providers'?'provider':kind;const name=state.forms[key+'-name']??(state.newRecord?'':currentItem(kind).name);if(!name.trim()){toast('请先填写名称。');return;}if(kind==='providers'){const url=state.forms['provider-url']??(state.providerType==='Anthropic'?'https://api.anthropic.com':state.providerType==='Gemini'?'https://generativelanguage.googleapis.com':'https://api.example.com/v1');let valid=false;try{valid=['https:','http:'].includes(new URL(url).protocol)}catch{}if(!valid){toast('请填写有效的 HTTP / HTTPS API 地址。');return;}const m=state.forms['provider-model']??currentItem('providers').model;if(!m?.trim()){toast('请先填写默认模型 ID。');return;}}
if(kind==='agents'&&!state.toolAll&&!state.toolSelections.size){toast('请至少选择一个工具；空列表在当前模型中表示全部工具。');return;}
const arr=({agents,providers,skills,memory:memories})[kind];const item=state.newRecord?{id:'demo-'+Date.now(),glyph:'A',model:'跟随全局',tools:'全部工具',date:'刚刚更新',version:'1.0.0',license:'MIT'}:currentItem(kind);item.name=name.trim();item.description=state.forms[key+'-description']??state.forms[key+'-body']??item.description??'';if(kind==='providers'){item.type=state.providerType;item.description=state.providerType+' 协议';item.model=state.forms['provider-model']??item.model;item.glyph='M';}if(kind==='skills'){item.version=state.forms['skill-version']??item.version;item.license=state.forms['skill-license']??item.license;}if(kind==='agents'){item.tools=state.toolAll?'全部工具':state.toolSelections.size+' 项工具';item.model=state.forms['agent-model']||'跟随全局';}if(state.newRecord)arr.push(item);state.newRecord=false;state.forms={};navigate(kind);toast('已保存到原型内存；刷新页面恢复演示数据。');}
function handleV1(act){const parts=act.split(':');const verb=parts[0];const val=parts.slice(1).join(':');if(verb==='go'){navigate(val);return}if(verb==='sheet'){if((state.screen==='running'&&!state.runStopped)&&['model','permissions','message-edit','message-menu','attach','attachment','compact'].includes(val)){toast('当前正在执行，请先停止或等待完成。');return;}show(val);return}if(verb==='review-sheet'){const baseScreen=({import:'backup',export:'backup',attachment:'chat',approval:'running',compact:'chat'})[val]||'chat';navigate(baseScreen);show(val);return}if(verb==='toast'){toast(val);return}if(verb==='suggest'){state.draft=val;render();document.getElementById('message-input')?.focus();return}if(verb==='theme-mode'){state.themeMode=val;state.theme=val==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):val;render();return}if(verb==='default-provider'){state.selectedProviderId=val;render();toast('已更新全局默认 Provider（演示），不覆盖既有会话 override。');return}if(verb==='model'){state.model=val;close();render();toast('已更新当前会话模型，未修改全局配置。');return}if(verb==='reasoning'){state.reasoning=val;close();render();toast(state.screen==='running'?'将在下一次模型请求生效。':'已更新会话思考强度。');return}if(verb==='permission-draft'){state.permissionDraft=val;renderOverlay();return}if(verb==='choose-agent'){state.agent=val;close();render();return}if(verb==='use-agent'){state.agent=val;state.draft='';state.attachments=[];navigate('home');return}if(verb==='bind-model'){state.forms['agent-model']=val;close();render();return}if(verb==='sub-model'){state.subModel=val;state.forceChild=val!=='继承主代理';close();render();return}if(verb==='filetab'){state.fileTab=val;render();return}if(verb==='plan-mode'){state.planMode=val;render();return}if(verb==='import-mode'){state.importMode=val;renderOverlay();return}if(verb==='delivery'){state.mediaDelivery=val;close();render();toast('已更新附件读取方式（示例）。');return}if(verb==='add-attachment'){state.attachments.push(val);close();render();return}if(verb==='toggle'){state[val]=!state[val];render();return}if(verb==='list-menu'){state.listKind=val;show('list-menu');return}if(verb==='manage'){state.listKind=val;state.manage=!state.manage;state.selected.clear();close();render();return}if(verb==='select'){state.selected.has(val)?state.selected.delete(val):state.selected.add(val);render();return}if(verb==='select-all'){const arr=({history:conversations,agents,providers,files,skills,memory:memories})[val]||[];arr.filter(matches).forEach(x=>state.selected.add(x.id));render();return}if(verb==='create'){state.newRecord=true;state.editId=null;state.forms={};if(val==='providers')state.providerType='Anthropic';navigate(({agents:'agent-edit',providers:'provider-edit',skills:'skill-edit',memory:'memory-edit'})[val]);return}if(verb==='edit'){state.newRecord=false;state.forms={};state.editId=parts[2];if(parts[1]==='providers')state.providerType=providers.find(p=>p.id===state.editId)?.type||'Anthropic';navigate(({agents:'agent-edit',providers:'provider-edit',skills:'skill-edit',memory:'memory-edit'})[parts[1]]);return}if(verb==='save'){save(val);return}if(verb==='export'){state.exportKind=val;state.keys=false;state.includeChats=false;show('export');return}if(verb==='import'){state.exportKind=val;state.importMode='copy';show(val==='skills'?'skill-import':'import');return}if(verb==='delete-current'){state.listKind=val;state.selected=new Set([currentItem(val).id]);show('delete');return}if(verb==='remove-command'){state.commandList.splice(Number(val),1);render();toast('已从精确命令列表移除。');return}if(verb==='avatar'){const a=currentItem('agents');a.glyph=val;close();render();return}
switch(act){case'drawer':show('drawer');break;case'close':close();break;case'back':navigate(state.stack.pop()||'home',false);break;case'new-chat':state.draft='';state.attachments=[];state.runStopped=false;state.messageDeleted=false;state.agent='通用助手';navigate('home');break;case'send':if(!state.draft.trim()&&!state.attachments.length)return;state.chatText=state.draft||'请查看这些附件。';state.draft='';state.runStopped=false;state.approvalDone=false;navigate('running');break;case'stop':state.runStopped=true;navigate('chat');toast('已停止演示任务；已有消息和文件记录保留。');break;case'resend':state.runStopped=false;navigate('running');toast('模拟重新发送。不会调用任何模型。');break;case'copy':{const text=state.forms['message-edit']||'已经整理好了。我把改进拆成三个阶段，优先解决日常使用中最明显的阻力。';if(navigator.clipboard?.writeText){navigator.clipboard.writeText(text).then(()=>toast('已复制示例文本。')).catch(()=>toast('浏览器未允许剪贴板，请选择正文手动复制。'));}else{toast('浏览器未允许剪贴板，请选择正文手动复制。')}break}case'download-file':download('iteration-plan-demo.md',planText);toast('已导出示例 Markdown。');break;case'theme-toggle':state.theme=state.theme==='light'?'dark':'light';state.themeMode=state.theme;render();break;case'width-360':document.getElementById('phone').classList.add('compact');renderReview();break;case'width-412':document.getElementById('phone').classList.remove('compact');renderReview();break;case'unknown-toggle':state.unknown=!state.unknown;renderOverlay();break;case'permission-save':if((state.permissionDraft||state.permission)==='Auto'){show('auto-confirm');}else{const dirs=(state.forms.scope||'').split('\n').filter(Boolean);if(dirs.some(d=>!d.trim().startsWith('/'))){toast('目录必须是 Android 绝对路径，例如 /storage/emulated/0/Download。');break;}state.permission=state.permissionDraft||state.permission;state.scope=state.forms.scope||'';close();render();toast('已更新会话权限与目录（演示）。')}break;case'auto-accept':if((state.forms.scope||'').split('\n').filter(Boolean).some(d=>!d.trim().startsWith('/'))){toast('目录必须是 Android 绝对路径。');break;}state.permission='Auto';state.scope=state.forms.scope||'';close();if(state.screen==='plan'){navigate('running');toast('已批准计划，使用 Auto（演示）。')}else{render();toast('已启用 Auto；不扩大 Android 系统权限。')}break;case'compact-start':show('compacting');compactTimer=setTimeout(()=>{state.compacted=true;state.overlay=null;render();toast('演示压缩已完成；原始消息保留。');},2600);break;case'compact-cancel':clearTimeout(compactTimer);state.overlay=null;render();toast('已取消压缩，未提交摘要。');break;case'allow-command':if(document.getElementById('approve-command')?.checked&&!state.commandList.includes('pwd'))state.commandList.push('pwd');state.approvalDone=true;close();navigate('chat');toast('已模拟允许并完成任务，没有执行系统命令。');break;case'deny-command':close();state.runStopped=true;navigate('chat');toast('已拒绝示例命令；主代理会收到拒绝结果。');break;case'plan-feedback':if(!(state.forms['plan-feedback']||'').trim()){toast('请先填写你希望修改的地方。');break;}navigate('chat');toast('修改意见已交回主代理（演示），尚未授权执行。');break;case'plan-accept':if(state.planMode==='Auto'){show('auto-confirm')}else{state.permission='Accept Edit';navigate('running');toast('已批准计划，执行仍遵守 Accept Edit。')}break;case'child-completed':navigate('child');toast('展示统一子代理会话布局；此条使用演示内容。');break;case'stop-child':state.childStopped=true;close();render();toast('子代理已中止，理由将反馈给主代理（演示）。');break;case'remove-attachment':state.attachments.shift();close();render();toast('已从本次输入移除；工作区文件不删除。');break;case'message-save':state.historyEdited=true;state.compacted=false;close();render();toast('已保存消息正文，清除上下文摘要与上次用量演示状态。');break;case'message-delete':state.listKind='message';state.selected=new Set(['msg']);show('delete');break;case'delete-confirm':{const arr=({history:conversations,agents,providers,files,skills,memory:memories})[state.listKind];if(arr){for(let i=arr.length-1;i>=0;i--)if(state.selected.has(arr[i].id))arr.splice(i,1);}state.selected.clear();close();if(state.listKind==='message'){state.historyEdited=true;state.compacted=false;state.messageDeleted=true;}else if(state.screen.endsWith('edit'))navigate(state.listKind);render();toast(state.listKind==='message'?'已移除演示消息；未撤销任何工具操作。':'已删除选中的演示数据。刷新可恢复。');break}case'export-demo':{const d={prototypeOnly:true,notImportable:true,scope:state.exportKind,count:state.selected.size||'all-demo-items',includeCredentialsRequested:state.keys,credentialsExported:false,includeOwnedConversations:state.includeChats,note:'UI演示清单，不是AgentApp实际备份；不包含API Key。'};download('agentapp-ui-demo-export.json',JSON.stringify(d,null,4),'application/json');close();toast('已导出 UI 演示清单，不是可恢复备份。');break}case'import-confirm':close();toast('已演示“'+(state.importMode==='copy'?'作为副本':'更新已有')+'”导入确认；未写入真实配置。');break;case'restore-demo':close();toast('恢复确认流程已演示；未覆盖任何真实数据。');break;case'command-review':if(!(state.forms['new-command']||'pwd').trim()){toast('请填写完整命令。');break;}show('confirm-command');break;case'command-save':{const c=(state.forms['new-command']||'pwd').trim();if(!state.commandList.includes(c))state.commandList.push(c);close();render();toast('已加入原型精确命令列表；未执行命令。');break}case'storage-demo':toast('原生实现：打开 Android 授权设置，返回后刷新实际权限状态。');break;case'reveal-key':{let el=document.getElementById('api-key');if(el)el.type=el.type==='password'?'text':'password';break}case'test-connection-start':state.connectionTest='testing';renderOverlay();setTimeout(()=>{state.connectionTest='done';if(state.overlay==='test-connection')renderOverlay();},900);break;case'skill-import-demo':close();toast('已展示 Skill ZIP 导入流程；未写入实际技能目录。');break;case'fetch-models':show('provider-models');toast('显示固定示例列表，不发起网络请求。');break;case'open-folder':state.forms.folder=true;render(false);break;case'close-folder':state.forms.folder=false;render(false);break;case'reset':reset();break;}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;handle(b.dataset.action);});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='message-input'){state.draft=el.value;const send=document.querySelector('.send');if(send&&!(state.screen==='running'&&!state.runStopped))send.disabled=!state.draft.trim()&&!state.attachments.length;}if(el.dataset.field)state.forms[el.dataset.field]=el.value;if(el.id==='max-loops'){state.maxLoops=Number(el.value);const y=document.querySelector('.content').scrollTop;render();document.querySelector('.content').scrollTop=y;}if(el.dataset.search){const start=el.selectionStart,q=el.value;state.query=q;if(state.overlay){renderOverlay();}else render();const fresh=document.querySelector(`[data-search="${el.dataset.search}"]`);fresh?.focus();fresh?.setSelectionRange(start,start);}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='provider-type'){state.providerType=el.value;delete state.forms['provider-url'];render();}if(el.id==='export-keys'){state.keys=el.checked;renderOverlay();}if(el.id==='export-chats')state.includeChats=el.checked;if(el.dataset.tool){el.checked?state.toolSelections.add(el.dataset.tool):state.toolSelections.delete(el.dataset.tool);}if(el.dataset.field)state.forms[el.dataset.field]=el.value;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.overlay){e.preventDefault();close();}if(e.key==='Tab'&&state.overlay){const d=document.querySelector('[role=dialog]');const f=Array.from(d?.querySelectorAll('button:not(:disabled),input,textarea,select,[tabindex="0"]')||[]).filter(el=>el.getClientRects().length);if(!f.length)return;const first=f[0],last=f[f.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===d)){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&document.activeElement?.id==='message-input'){e.preventDefault();handle('send');}});
if(qs.get('embed')==='1')document.body.classList.add('embed');
// Cold entry is always the new conversation route unless an explicit review query is supplied.
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(screenMap[r]&&r!==state.screen)navigate(r,false);});
window.addEventListener('popstate',()=>{if(state.overlay)close();});
